/* Стоянка, що діє у вересні, для заданого місця. */
function stayOf(slot) {
  return STAYS.find(s => s.slot === slot && s.to === 30) || null;
}

/* Стоянка за номером рахунку. */
function stayByInvoice(no) {
  return STAYS.find(s => s.inv === no) || null;
}

